"""Expression evaluation for minisql.

The public surface of this module is described in the implementation contract:

    AGGREGATE_NAMES, EvalContext, contains_aggregate,
    validate_no_nested_aggregates, validate_no_aggregates, check_grouped,
    evaluate, compare_values, value_key

NULL is represented by ``None``.  Booleans are deliberately *not* numbers
(``bool`` is a subclass of ``int`` in Python), so numeric helpers check for
``bool`` explicitly.
"""

import re
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext
from typing import Any, Iterator, List, Optional, Sequence, Set, Tuple

from . import ast
from .errors import QueryError

__all__ = [
    "AGGREGATE_NAMES",
    "EvalContext",
    "contains_aggregate",
    "validate_no_nested_aggregates",
    "validate_no_aggregates",
    "check_grouped",
    "evaluate",
    "compare_values",
    "value_key",
]

AGGREGATE_NAMES = frozenset({"COUNT", "SUM", "AVG", "MIN", "MAX"})

_SCALAR_FUNCTIONS = frozenset(
    {"LOWER", "UPPER", "LENGTH", "ABS", "ROUND", "COALESCE"}
)

_COMPARISON_OPS = frozenset({"=", "!=", "<>", "<", "<=", ">", ">="})
_ARITHMETIC_OPS = frozenset({"+", "-", "*", "/"})


# ---------------------------------------------------------------------------
# Context
# ---------------------------------------------------------------------------


class EvalContext:
    """Evaluation context for a single row, or for a group of rows.

    ``headers`` are the canonical CSV header spellings, ``row`` is the row
    against which plain columns are evaluated, and ``group_rows`` is ``None``
    for an ungrouped row or a sequence of rows when aggregates may be used.
    """

    def __init__(self, headers, row, group_rows=None):
        self.headers = list(headers)
        self.row = row
        self.group_rows = group_rows
        self._index = {}
        for index, header in enumerate(self.headers):
            # Column matching is case-insensitive.  Keep the first occurrence
            # in case a CSV happens to repeat a header.
            self._index.setdefault(header.casefold(), index)

    def resolve(self, name: str) -> int:
        """Return the zero-based index of ``name`` (case-insensitive)."""
        if not isinstance(name, str):
            raise QueryError("column name must be a string")
        try:
            return self._index[name.casefold()]
        except KeyError:
            raise QueryError("unknown column: %s" % (name,)) from None

    def column_value(self, name: str) -> Any:
        """Return this row's value for ``name``."""
        index = self.resolve(name)
        try:
            return self.row[index]
        except (IndexError, TypeError):
            raise QueryError(
                "column %s has no value in this row" % (name,)
            ) from None


# ---------------------------------------------------------------------------
# Small value helpers
# ---------------------------------------------------------------------------


def _is_number(value: Any) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def _require_number(value: Any, what: str) -> Any:
    if not _is_number(value):
        raise QueryError("%s requires a numeric operand" % (what,))
    return value


def _require_bool(value: Any, what: str) -> Any:
    if value is None or isinstance(value, bool):
        return value
    raise QueryError("%s requires a boolean operand" % (what,))


def _type_name(value: Any) -> str:
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "a boolean"
    if isinstance(value, int):
        return "an integer"
    if isinstance(value, float):
        return "a number"
    if isinstance(value, str):
        return "a string"
    return type(value).__name__


def value_key(value: Any):
    """A hashable key for a value.

    Numbers compare consistently (``value_key(1) == value_key(1.0)``), while
    booleans are kept distinct from numbers.
    """
    if value is None:
        return ("null",)
    if isinstance(value, bool):
        return ("bool", value)
    if isinstance(value, (int, float)):
        return ("num", value)
    return ("str", value)


def compare_values(a: Any, b: Any) -> int:
    """Compare two values, returning -1, 0, or 1.

    NULLs sort before non-NULL values (the engine additionally decides where
    NULLs belong in ORDER BY).  Comparing incompatible types is an error.
    """
    if a is None or b is None:
        if a is None and b is None:
            return 0
        return -1 if a is None else 1

    a_is_bool = isinstance(a, bool)
    b_is_bool = isinstance(b, bool)
    if a_is_bool or b_is_bool:
        if not (a_is_bool and b_is_bool):
            raise QueryError(
                "cannot compare %s with %s"
                % (_type_name(a), _type_name(b))
            )
        if a is b or a == b:
            return 0
        return -1 if not a else 1

    a_is_num = _is_number(a)
    b_is_num = _is_number(b)
    if a_is_num or b_is_num:
        if not (a_is_num and b_is_num):
            raise QueryError(
                "cannot compare %s with %s"
                % (_type_name(a), _type_name(b))
            )
        if a < b:
            return -1
        if a > b:
            return 1
        return 0

    if isinstance(a, str) and isinstance(b, str):
        if a < b:
            return -1
        if a > b:
            return 1
        return 0

    raise QueryError(
        "cannot compare %s with %s" % (_type_name(a), _type_name(b))
    )


# ---------------------------------------------------------------------------
# AST inspection helpers
# ---------------------------------------------------------------------------


def _is_aggregate(node: Any) -> bool:
    return (
        isinstance(node, ast.Func)
        and isinstance(node.name, str)
        and node.name.upper() in AGGREGATE_NAMES
    )


def contains_aggregate(expr: Any) -> bool:
    """Return True if ``expr`` contains an aggregate function."""
    if expr is None:
        return False
    return any(_is_aggregate(node) for node in ast.walk(expr))


def validate_no_nested_aggregates(expr: Any) -> None:
    """Raise ``QueryError`` if an aggregate contains another aggregate."""
    if expr is None:
        return
    for node in ast.walk(expr):
        if _is_aggregate(node):
            for arg in node.args:
                for descendant in ast.walk(arg):
                    if _is_aggregate(descendant):
                        raise QueryError(
                            "aggregate functions may not be nested"
                        )


def validate_no_aggregates(expr: Any, clause: str) -> None:
    """Raise ``QueryError`` if ``expr`` contains an aggregate."""
    if expr is None:
        return
    if contains_aggregate(expr):
        where = " in %s" % (clause,) if clause else ""
        raise QueryError("aggregate functions are not allowed%s" % (where,))


def _iter_children(node: Any) -> Iterator[Any]:
    if isinstance(node, ast.Unary):
        yield node.operand
    elif isinstance(node, ast.Binary):
        yield node.left
        yield node.right
    elif isinstance(node, ast.IsNull):
        yield node.operand
    elif isinstance(node, ast.InList):
        yield node.operand
        for item in node.items:
            yield item
    elif isinstance(node, ast.Between):
        yield node.operand
        yield node.low
        yield node.high
    elif isinstance(node, ast.Like):
        yield node.operand
        yield node.pattern
    elif isinstance(node, ast.Func):
        for arg in node.args:
            yield arg


def check_grouped(expr: Any, group_by_exprs: Sequence[Any]) -> None:
    """Validate that bare columns are covered by the GROUP BY expressions.

    A subtree structurally equal to a GROUP BY expression is acceptable and is
    not descended into.  Aggregate arguments are also outside the check.
    """
    if expr is None:
        return

    group_keys = set()
    for group_expr in group_by_exprs or ():
        group_keys.add(ast.expr_key(group_expr))

    def visit(node: Any) -> None:
        if node is None:
            return
        try:
            key = ast.expr_key(node)
        except TypeError:
            key = None
        if key is not None and key in group_keys:
            return
        if _is_aggregate(node):
            return
        if isinstance(node, ast.Column):
            raise QueryError(
                "column %s must appear in GROUP BY or be used in an "
                "aggregate function" % (node.name,)
            )
        for child in _iter_children(node):
            visit(child)

    visit(expr)


# ---------------------------------------------------------------------------
# Three-valued logic helpers
# ---------------------------------------------------------------------------


def _and3(a: Optional[bool], b: Optional[bool]) -> Optional[bool]:
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or3(a: Optional[bool], b: Optional[bool]) -> Optional[bool]:
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


# ---------------------------------------------------------------------------
# Evaluation
# ---------------------------------------------------------------------------


def evaluate(expr: Any, ctx: EvalContext) -> Any:
    """Evaluate ``expr`` in ``ctx``."""
    if isinstance(expr, ast.Literal):
        return expr.value
    if isinstance(expr, ast.Column):
        return ctx.column_value(expr.name)
    if isinstance(expr, ast.Star):
        raise QueryError("'*' is only allowed in COUNT(*)")
    if isinstance(expr, ast.Unary):
        return _eval_unary(expr, ctx)
    if isinstance(expr, ast.Binary):
        return _eval_binary(expr, ctx)
    if isinstance(expr, ast.IsNull):
        value = evaluate(expr.operand, ctx)
        is_null = value is None
        return (not is_null) if expr.negated else is_null
    if isinstance(expr, ast.InList):
        return _eval_in(expr, ctx)
    if isinstance(expr, ast.Between):
        return _eval_between(expr, ctx)
    if isinstance(expr, ast.Like):
        return _eval_like(expr, ctx)
    if isinstance(expr, ast.Func):
        return _eval_func(expr, ctx)
    raise QueryError("unsupported expression: %r" % (expr,))


def _eval_unary(expr: ast.Unary, ctx: EvalContext) -> Any:
    op = expr.op.upper() if isinstance(expr.op, str) else expr.op
    value = evaluate(expr.operand, ctx)

    if op == "NOT":
        value = _require_bool(value, "NOT")
        return None if value is None else not value
    if op == "-":
        if value is None:
            return None
        _require_number(value, "unary -")
        return -value
    raise QueryError("unknown unary operator: %s" % (expr.op,))


def _eval_binary(expr: ast.Binary, ctx: EvalContext) -> Any:
    op = expr.op.upper() if isinstance(expr.op, str) else expr.op

    if op in ("AND", "OR"):
        left = _require_bool(evaluate(expr.left, ctx), op)
        right = _require_bool(evaluate(expr.right, ctx), op)
        return _and3(left, right) if op == "AND" else _or3(left, right)

    left = evaluate(expr.left, ctx)
    right = evaluate(expr.right, ctx)

    if op == "||":
        if left is None or right is None:
            return None
        return str(left) + str(right)

    if op in _COMPARISON_OPS:
        if left is None or right is None:
            return None
        comparison = compare_values(left, right)
        if op == "=":
            return comparison == 0
        if op in ("!=", "<>"):
            return comparison != 0
        if op == "<":
            return comparison < 0
        if op == "<=":
            return comparison <= 0
        if op == ">":
            return comparison > 0
        return comparison >= 0

    if op in _ARITHMETIC_OPS:
        if left is None or right is None:
            return None
        _require_number(left, "'%s'" % (op,))
        _require_number(right, "'%s'" % (op,))
        return _arithmetic(op, left, right)

    raise QueryError("unknown binary operator: %s" % (expr.op,))


def _arithmetic(op: str, left: Any, right: Any) -> Any:
    if op == "/":
        try:
            return left / right
        except ZeroDivisionError:
            return None

    both_int = isinstance(left, int) and isinstance(right, int)
    if both_int:
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        return left * right

    a = float(left)
    b = float(right)
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    return a * b


def _eval_in(expr: ast.InList, ctx: EvalContext) -> Any:
    subject = evaluate(expr.operand, ctx)
    if subject is None:
        return None

    saw_null = False
    for item_expr in expr.items:
        item = evaluate(item_expr, ctx)
        if item is None:
            saw_null = True
            continue
        if compare_values(subject, item) == 0:
            return False if expr.negated else True

    if saw_null:
        return None
    return True if expr.negated else False


def _eval_between(expr: ast.Between, ctx: EvalContext) -> Any:
    subject = evaluate(expr.operand, ctx)
    low = evaluate(expr.low, ctx)
    high = evaluate(expr.high, ctx)

    low_ok = (
        None
        if subject is None or low is None
        else compare_values(low, subject) <= 0
    )
    high_ok = (
        None
        if subject is None or high is None
        else compare_values(subject, high) <= 0
    )

    result = _and3(low_ok, high_ok)
    if expr.negated and result is not None:
        result = not result
    return result


def _like_regex(pattern: str) -> "re.Pattern":
    parts = []
    for char in pattern:
        if char == "%":
            parts.append(".*")
        elif char == "_":
            parts.append(".")
        else:
            parts.append(re.escape(char))
    return re.compile("".join(parts), re.DOTALL)


def _eval_like(expr: ast.Like, ctx: EvalContext) -> Any:
    subject = evaluate(expr.operand, ctx)
    pattern = evaluate(expr.pattern, ctx)
    if subject is None or pattern is None:
        return None
    if not isinstance(subject, str):
        raise QueryError("LIKE requires a string operand")
    if not isinstance(pattern, str):
        raise QueryError("LIKE requires a string pattern")

    matched = _like_regex(pattern).fullmatch(subject) is not None
    if expr.negated:
        matched = not matched
    return matched


# ---------------------------------------------------------------------------
# Functions
# ---------------------------------------------------------------------------


def _check_arity(expr: ast.Func, name: str, allowed) -> None:
    if expr.star or len(expr.args) not in allowed:
        raise QueryError(
            "%s has the wrong number of arguments" % (name,)
        )


def _eval_func(expr: ast.Func, ctx: EvalContext) -> Any:
    if not isinstance(expr.name, str):
        raise QueryError("invalid function name")
    name = expr.name.upper()

    if name in AGGREGATE_NAMES:
        return _eval_aggregate(name, expr, ctx)
    if name not in _SCALAR_FUNCTIONS:
        raise QueryError("unknown function: %s" % (expr.name,))
    if expr.star:
        raise QueryError("%s does not accept '*'" % (name,))

    if name in ("LOWER", "UPPER", "LENGTH"):
        _check_arity(expr, name, (1,))
        value = evaluate(expr.args[0], ctx)
        if value is None:
            return None
        if not isinstance(value, str):
            raise QueryError("%s requires a string argument" % (name,))
        if name == "LOWER":
            return value.lower()
        if name == "UPPER":
            return value.upper()
        return len(value)

    if name == "ABS":
        _check_arity(expr, name, (1,))
        value = evaluate(expr.args[0], ctx)
        if value is None:
            return None
        _require_number(value, "ABS")
        return abs(value)

    if name == "ROUND":
        _check_arity(expr, name, (1, 2))
        value = evaluate(expr.args[0], ctx)
        if value is None:
            return None
        _require_number(value, "ROUND")
        if len(expr.args) == 1:
            return _round_to_int(value)
        places = evaluate(expr.args[1], ctx)
        if places is None:
            return None
        if not isinstance(places, int) or isinstance(places, bool):
            raise QueryError(
                "ROUND's second argument must be an integer"
            )
        return _round_to_places(value, places)

    # COALESCE
    if not expr.args:
        raise QueryError("COALESCE expects at least one argument")
    for arg in expr.args:
        value = evaluate(arg, ctx)
        if value is not None:
            return value
    return None


def _quantize(value: Any, places: int) -> Decimal:
    decimal_value = Decimal(str(value))
    if not decimal_value.is_finite():
        raise QueryError("cannot round a non-finite number")

    digits = len(decimal_value.as_tuple().digits)
    if places < 0 and -places > digits + 2:
        return Decimal(0)

    # Keep memory use bounded for absurdly large second arguments.  Beyond
    # this many places a float cannot represent any additional precision.
    effective_places = min(places, 400)
    quantum = Decimal(1).scaleb(-effective_places)
    try:
        with localcontext() as context:
            context.prec = max(28, digits + abs(effective_places) + 2)
            context.rounding = ROUND_HALF_UP
            return decimal_value.quantize(quantum)
    except (InvalidOperation, ValueError):
        raise QueryError(
            "cannot round %s to %s decimal places" % (value, places)
        ) from None


def _round_to_int(value: Any) -> int:
    if isinstance(value, int):
        return value
    try:
        return int(_quantize(value, 0))
    except OverflowError:
        raise QueryError("number is too large to round") from None


def _round_to_places(value: Any, places: int) -> float:
    try:
        return float(_quantize(value, places))
    except OverflowError:
        raise QueryError("number is too large to round") from None


def _group_context(ctx: EvalContext, row: Any) -> EvalContext:
    return EvalContext(ctx.headers, row, None)


def _eval_aggregate(name: str, expr: ast.Func, ctx: EvalContext) -> Any:
    if ctx.group_rows is None:
        raise QueryError(
            "%s is only allowed in a grouped query" % (name,)
        )

    if name == "COUNT":
        if expr.star:
            if expr.args:
                raise QueryError("COUNT(*) takes no arguments")
            return len(ctx.group_rows)
        _check_arity(expr, name, (1,))
        arg = expr.args[0]
        if contains_aggregate(arg):
            raise QueryError("aggregate functions may not be nested")
        count = 0
        for row in ctx.group_rows:
            if evaluate(arg, _group_context(ctx, row)) is not None:
                count += 1
        return count

    _check_arity(expr, name, (1,))
    arg = expr.args[0]
    if contains_aggregate(arg):
        raise QueryError("aggregate functions may not be nested")

    if name in ("MIN", "MAX"):
        best = None
        found = False
        for row in ctx.group_rows:
            value = evaluate(arg, _group_context(ctx, row))
            if value is None:
                continue
            if not found:
                best = value
                found = True
                continue
            comparison = compare_values(value, best)
            if (name == "MIN" and comparison < 0) or (
                name == "MAX" and comparison > 0
            ):
                best = value
        return best

    total = None
    count = 0
    for row in ctx.group_rows:
        value = evaluate(arg, _group_context(ctx, row))
        if value is None:
            continue
        if not _is_number(value):
            raise QueryError("%s requires numeric values" % (name,))
        count += 1
        if total is None:
            total = value
        elif isinstance(total, int) and isinstance(value, int):
            total = total + value
        else:
            total = float(total) + float(value)

    if total is None:
        return None
    if name == "SUM":
        return total
    # AVG is always a float.
    return total / count

