"""Aggregates, grouping, HAVING, DISTINCT, and output names."""

import unittest

from tests.support import MiniSQLTestCase


class AggregateTestCase(MiniSQLTestCase):
    def setUp(self):
        super().setUp()
        self.write_csv(
            "sales",
            ["region", "amount"],
            [
                ["north", 10],
                ["south", 5],
                ["north", 20],
                ["east", ""],
                ["south", 15],
            ],
        )
        self.write_csv(
            "names",
            ["name"],
            [["alice"], ["bob"], ["carol"]],
        )
        self.write_csv("nums", ["v"], [[1], [1.0], [2]])
        self.write_csv(
            "nulls",
            ["k", "v"],
            [["", 1], ["", 2], ["x", 3]],
        )
        self.write_csv(
            "pairs",
            ["a", "b"],
            [[1, 1], [1, 2], [2, 1], [1, 1]],
        )
        self.write_csv("floats", ["v"], [[1.5], [2.5]])
        self.write_csv("mixed", ["v"], [[1], [2.5]])


class AggregateTests(AggregateTestCase):
    def test_count_star_counts_rows(self):
        self.assertEqual(self.rows("SELECT COUNT(*) FROM sales"), [(5,)])

    def test_count_expression_ignores_nulls(self):
        self.assertEqual(self.rows("SELECT COUNT(amount) FROM sales"), [(4,)])

    def test_count_of_literal_counts_non_null_values(self):
        self.assertEqual(self.rows("SELECT COUNT(1) FROM sales"), [(5,)])
        self.assertEqual(self.rows("SELECT COUNT(NULL) FROM sales"), [(0,)])

    def test_sum_ignores_nulls_and_keeps_integer_type(self):
        rows = self.rows("SELECT SUM(amount) FROM sales")
